/* ---------- Step loader ---------- */
.stl .dm-main{gap:10px}
.stl-row{display:flex;align-items:center;gap:10px;background:var(--surface);border-radius:var(--r-pill);box-shadow:var(--shadow);height:40px;padding:0 14px 0 13px;font-size:13.5px;min-width:250px;transition:box-shadow .3s}
@media (hover:hover) and (pointer:fine){.stl-row:hover{box-shadow:var(--shadow-pop)}}
.stl-g{width:16px;display:grid;place-items:center;color:var(--fg)}
.stl-t{flex:1;text-align:left}
.stl-n{color:var(--muted);font-size:12.5px}
.stl-chev{color:var(--muted);transition:transform .4s var(--ease)}
.stl-row[aria-expanded="true"] .stl-chev{transform:rotate(180deg)}
.stl-track{display:flex;gap:4px;width:250px}
.stl-track i{flex:1;height:3px;border-radius:2px;background:var(--line);position:relative;overflow:hidden}
.stl-track i::after{content:"";position:absolute;inset:0;background:var(--accent-mark,var(--accent));transform:scaleX(0);transform-origin:left;transition:transform .9s var(--ease)}
.stl-track i.on::after{transform:scaleX(1)}
.stl-track i.run::after{transform:scaleX(.45);transition-duration:2.2s}
.stl-fold{width:250px}
.stl-fold>div{margin-inline:-16px;padding-inline:16px}
.stl-list{list-style:none;margin:6px 0 18px;padding:6px;background:var(--surface);border-radius:14px;box-shadow:var(--shadow)}
.stl-list li{display:flex;align-items:center;gap:9px;padding:6px 8px;font-size:13px;color:var(--muted)}
.stl-list li.done{color:var(--fg2)}.stl-list li.run{color:var(--fg)}
.stl-list li .g{width:14px;display:grid;place-items:center}
.bars3{display:inline-flex;gap:2px;align-items:center;height:12px}
.bars3 i{width:2.5px;height:100%;border-radius:2px;background:currentColor;animation:b3 .9s var(--ease-io) infinite}
.bars3 i:nth-child(2){animation-delay:.15s}.bars3 i:nth-child(3){animation-delay:.3s}
@keyframes b3{0%,100%{transform:scaleY(.35)}50%{transform:scaleY(1)}}

DM.def('step-loader', (r, c) => {
  const steps = [['Reading Figma frames','Read 4 frames'],['Matching tokens','Matched 18 tokens'],['Writing components','Wrote 3 components'],['Checking contrast','Contrast passes']];
  const row = $('.stl-row', r), lab = $('.stl-lab', r), n = $('.stl-n', r), g = $('.stl-g', r), bars = $$('.stl-track i', r), list = $('.stl-list', r), fold = $('.stl-fold', r);
  let kind = 'radar', cur = 0, done = false;
  const glyph = () => kind === 'radar' ? '<span class="radar"></span>' : kind === 'think' ? '<span class="think on"><i></i><i></i><i></i><i></i></span>' : kind === 'spin' ? '<span class="spin"></span>' : '<span class="bars3"><i></i><i></i><i></i></span>';
  const paint = () => {
    g.innerHTML = done ? `<span style="color:var(--ok)">${I('ok')}</span>` : glyph();
    list.innerHTML = steps.map((s, i) => `<li class="${i < cur || done ? 'done' : i === cur ? 'run' : ''}"><span class="g">${i < cur || done ? `<span style="color:var(--ok)">${I('check','xs')}</span>` : i === cur ? glyph() : '<span class="dot" style="color:var(--faint)"></span>'}</span>${i < cur || done ? s[1] : s[0]}</li>`).join('');
  };
  seg($('.seg2', r), v => { kind = v; paint(); });
  row.onclick = () => { const o = fold.classList.toggle('shut'); row.setAttribute('aria-expanded', !o); };
  paint();
  c.run(async () => {
    for (;;){
      for (cur = 0; cur < steps.length; cur++){
        bars[cur].classList.add('run'); paint();
        swap(lab, steps[cur][0]); swap(n, (cur + 1) + '/4');
        await c.wait(1900);
        bars[cur].classList.remove('run'); bars[cur].classList.add('on');
      }
      done = true; lab.classList.remove('shim'); swap(lab, 'Ready for review'); swap(n, '4/4'); paint();
      /* hold the finished state, then run the steps again */
      await c.wait(3200);
      done = false; cur = 0; bars.forEach(b => b.classList.remove('on', 'run')); lab.classList.add('shim'); paint();
      await c.wait(700);
    }
  });
});
